        { label: { en: "AI-generated", fr: "Générée par IA", es: "Generada por IA", de: "KI-generiert", it: "Generata dall'IA", da: "AI-genereret", bg: "Генерирана от AI", tr: "AI tarafından üretilmiş" }, next: "q2_explain", reaction: { en: "Surprise — it's real!", fr: "Surprise — c'est une vraie photo !", es: "Sorpresa — ¡es real!", de: "Überraschung — es ist echt!", it: "Sorpresa — è vera!", da: "Overraskelse — den er ægte!", bg: "Изненада — истинска е!", tr: "Sürpriz — gerçek!" } }
